// FieldsWithPresence returns the fields of a file at a given presence,
// and whether the file is one the spec describes at all.
func FieldsWithPresence(filename string, presence FieldPresence) ([]string, bool) {
	fields, known := fieldPresenceByFile[filename]
	if !known {
		return nil, false
	}
	matching := make([]string, 0, len(fields))
	for field, actual := range fields {
		if actual == presence {
			matching = append(matching, field)
		}
	}
	return matching, true
}

